1	package com.example.starter.credit;
2	
3	import java.math.BigDecimal;
4	import java.sql.Timestamp;
5	import java.time.LocalDateTime;
6	import java.util.List;
7	
8	import com.example.starter.common.ApiException;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	/**
14	 * 开票方授信额度服务。
15	 * 可用额度＝总额度−未归档蓝票金额＋已确认红票金额，按公式实时复算；
16	 * 开票占用、红票确认恢复、归档释放均写入台账，台账可复算、重复查询结果稳定。
17	 */
18	@Service
19	public class CreditService {
20	
21	    private final JdbcTemplate jdbc;
22	
23	    public CreditService(JdbcTemplate jdbc) {
24	        this.jdbc = jdbc;
25	    }
26	
27	    /**
28	     * 创建开票方授信账户（合成数据）；已存在返回 409。
29	     */
30	    @Transactional
31	    public CreditView createAccount(CreateCreditAccountRequest request) {
32	        Integer exists = jdbc.queryForObject(
33	                "SELECT COUNT(*) FROM credit_account WHERE seller_id = ?",
34	                Integer.class, request.sellerId());
35	        if (exists != null && exists > 0) {
36	            throw ApiException.conflict("CREDIT_ACCOUNT_EXISTS", "授信账户已存在: " + request.sellerId());
37	        }
38	        jdbc.update("INSERT INTO credit_account (seller_id, total_limit) VALUES (?, ?)",
39	                request.sellerId(), request.totalLimit());
40	        return getCredit(request.sellerId());
41	    }
42	
43	    /**
44	     * 查询授信账户与实时可用额度。
45	     */
46	    @Transactional(readOnly = true)
47	    public CreditView getCredit(String sellerId) {
48	        BigDecimal totalLimit = jdbc.query(
49	                        "SELECT total_limit FROM credit_account WHERE seller_id = ?",
50	                        (rs, rowNum) -> rs.getBigDecimal("total_limit"), sellerId)
51	                .stream()
52	                .findFirst()
53	                .orElseThrow(() -> ApiException.notFound("CREDIT_ACCOUNT_NOT_FOUND", "授信账户不存在: " + sellerId));
54	        return new CreditView(sellerId, totalLimit, computeAvailable(sellerId));
55	    }
56	
57	    /**
58	     * 查询额度台账，按流水号升序，结果稳定可复算。
59	     */
60	    @Transactional(readOnly = true)
61	    public List<LedgerEntry> listLedger(String sellerId) {
62	        return jdbc.query(
63	                "SELECT id, seller_id, change_amount, reason, ref_no, available_after, created_at"
64	                        + " FROM credit_ledger WHERE seller_id = ? ORDER BY id",
65	                (rs, rowNum) -> new LedgerEntry(
66	                        rs.getLong("id"),
67	                        rs.getString("seller_id"),
68	                        rs.getBigDecimal("change_amount"),
69	                        rs.getString("reason"),
70	                        rs.getString("ref_no"),
71	                        rs.getBigDecimal("available_after"),
72	                        rs.getTimestamp("created_at").toLocalDateTime()),
73	                sellerId);
74	    }
75	
76	    /**
77	     * 按公式复算可用额度：总额度−未归档蓝票金额＋已确认红票金额。
78	     * 归档（ARCHIVED）蓝票不再占用；全额红冲蓝票占用与红票恢复相互抵销。
79	     */
80	    public BigDecimal computeAvailable(String sellerId) {
81	        BigDecimal result = jdbc.queryForObject(
82	                "SELECT a.total_limit"
83	                        + " - COALESCE((SELECT SUM(i.total_amount) FROM invoice i"
84	                        + "   WHERE i.seller_id = a.seller_id AND i.kind = 'BLUE' AND i.status <> 'ARCHIVED'), 0)"
85	                        + " + COALESCE((SELECT SUM(r.total_amount) FROM invoice r"
86	                        + "   WHERE r.seller_id = a.seller_id AND r.kind = 'RED'), 0)"
87	                        + " FROM credit_account a WHERE a.seller_id = ?",
88	                BigDecimal.class, sellerId);
89	        if (result == null) {
90	            throw ApiException.notFound("CREDIT_ACCOUNT_NOT_FOUND", "授信账户不存在: " + sellerId);
91	        }
92	        return result;
93	    }
94	
95	    /**
96	     * 对授信账户加行级悲观锁（须在事务内调用），用于开票/红冲串行校验。
97	     */
98	    public void lockAccount(String sellerId) {
99	        jdbc.query(
100	                        "SELECT seller_id FROM credit_account WHERE seller_id = ? FOR UPDATE",
101	                        (rs, rowNum) -> rs.getString("seller_id"), sellerId)
102	                .stream()
103	                .findFirst()
104	                .orElseThrow(() -> ApiException.notFound("CREDIT_ACCOUNT_NOT_FOUND", "授信账户不存在: " + sellerId));
105	    }
106	
107	    /**
108	     * 写入额度台账（须在事务内调用）。availableAfter 由调用方按变动前后额度计算。
109	     */
110	    public void appendLedger(String sellerId, BigDecimal changeAmount, String reason,
111	                             String refNo, BigDecimal availableAfter) {
112	        jdbc.update(
113	                "INSERT INTO credit_ledger (seller_id, change_amount, reason, ref_no, available_after)"
114	                        + " VALUES (?, ?, ?, ?, ?)",
115	                sellerId, changeAmount, reason, refNo, availableAfter);
116	    }
117	
118	    /**
119	     * 创建授信账户请求。
120	     *
121	     * @param sellerId   开票方ID
122	     * @param totalLimit 授信总额度，单位元
123	     */
124	    public record CreateCreditAccountRequest(String sellerId, BigDecimal totalLimit) {
125	    }
126	
127	    /**
128	     * 授信视图。
129	     *
130	     * @param sellerId       开票方ID
131	     * @param totalLimit     授信总额度，单位元
132	     * @param availableLimit 可用额度，单位元
133	     */
134	    public record CreditView(String sellerId, BigDecimal totalLimit, BigDecimal availableLimit) {
135	    }
136	
137	    /**
138	     * 额度台账条目。
139	     */
140	    public record LedgerEntry(Long id, String sellerId, BigDecimal changeAmount, String reason,
141	                              String refNo, BigDecimal availableAfter, LocalDateTime createdAt) {
142	    }
143	}
