55	    void cleanDatabase() {
56	        jdbc.update("DELETE FROM idempotency_record");
57	        jdbc.update("DELETE FROM red_flush_confirmation");
58	        jdbc.update("DELETE FROM red_flush_line");
59	        jdbc.update("DELETE FROM red_flush_request");
60	        jdbc.update("DELETE FROM invoice_line");
61	        jdbc.update("DELETE FROM invoice");
62	        jdbc.update("DELETE FROM credit_ledger");
63	        jdbc.update("DELETE FROM credit_account");
64	    }
