67	    static void shutdownDatabase(@Autowired JdbcTemplate jdbc) {
68	        // DB_CLOSE_DELAY=-1 下显式释放测试库，避免上下文结束后悬挂
69	        jdbc.execute("SHUTDOWN");
70	    }
71	
72	    @Test
73	    void 主流程_开票交付部分红冲后额度同事务恢复且台账可复算() {
74	        creditService.createAccount(new CreateCreditAccountRequest("S1", new BigDecimal("1000.00")));
75	        IssueResponse issued = issue("S1", "REQ-1",
76	                List.of(new LineRequest("货物A", new BigDecimal("250.00")),
77	                        new LineRequest("货物B", new BigDecimal("150.00"))));
78	        assertThat(issued.status()).isEqualTo("ISSUED");
79	        assertThat(issued.availableLimit()).isEqualByComparingTo("600.00");
80	
81	        invoiceService.deliver(issued.invoiceNo());
82	        assertThat(invoiceService.getInvoice(issued.invoiceNo()).status()).isEqualTo("DELIVERED");
83	
84	        CreateRedFlushResponse created = redFlushService.createRequest(new CreateRedFlushRequest(
85	                "RF-1", issued.invoiceNo(), "PARTIAL",
86	                List.of(new RedLineRequest(1, new BigDecimal("100.00")))));
87	        assertThat(created.result()).isEqualTo("CREATED");
88	        assertThat(created.status()).isEqualTo("PENDING");
89	
90	        // 单方确认不生效：无红票、额度不变
91	        ConfirmResponse first = redFlushService.confirm(created.requestNo(),
92	                new ConfirmRequest("SELLER", "AGREE"));
93	        assertThat(first.status()).isEqualTo("PENDING");
94	        assertThat(first.redInvoiceNo()).isNull();
95	        assertThat(creditService.getCredit("S1").availableLimit()).isEqualByComparingTo("600.00");
96	
97	        // 双方在同一事务内先后确认：开具红票并同事务恢复额度
98	        ConfirmResponse second = redFlushService.confirm(created.requestNo(),
99	                new ConfirmRequest("BUYER", "AGREE"));
100	        assertThat(second.status()).isEqualTo("ISSUED");
101	        assertThat(second.redInvoiceNo()).isNotNull();
102	        assertThat(second.availableLimit()).isEqualByComparingTo("700.00");
103	        assertThat(creditService.getCredit("S1").availableLimit()).isEqualByComparingTo("700.00");
104	
105	        InvoiceView view = invoiceService.getInvoice(issued.invoiceNo());
106	        assertThat(view.status()).isEqualTo("PARTIAL_RED");
107	        assertThat(view.redFlushedAmount()).isEqualByComparingTo("100.00");
108	        assertThat(view.redChain()).hasSize(1);
109	        assertThat(view.redChain().get(0).invoiceNo()).isEqualTo(second.redInvoiceNo());
110	        assertThat(view.redChain().get(0).amount()).isEqualByComparingTo("100.00");
111	
112	        // 台账可复算：总额度 + Σ变动 = 当前可用额度
113	        var ledger = creditService.listLedger("S1");
114	        assertThat(ledger).hasSize(2);
115	        assertThat(ledger.get(0).reason()).isEqualTo("ISSUE");
116	        assertThat(ledger.get(0).changeAmount()).isEqualByComparingTo("-400.00");
117	        assertThat(ledger.get(1).reason()).isEqualTo("RED_CONFIRM");
118	        assertThat(ledger.get(1).changeAmount()).isEqualByComparingTo("100.00");
119	        BigDecimal recomputed = new BigDecimal("1000.00")
120	                .add(ledger.stream().map(CreditService.LedgerEntry::changeAmount)
121	                        .reduce(BigDecimal.ZERO, BigDecimal::add));
122	        assertThat(recomputed).isEqualByComparingTo(
